import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DIRECTIONS = ['입금', '출금'];
const CYCLES = ['MONTHLY', 'QUARTERLY', 'YEARLY', 'ONCE'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

const COLUMNS =
  'fixed_fund_id AS "fixedFundId", ' +
  'fixed_fund_name AS "fixedFundName", ' +
  'fund_subject_id AS "fundSubjectId", ' +
  'amount AS "amount", ' +
  'cash_direction AS "cashDirection", ' +
  'occurrence_cycle AS "occurrenceCycle", ' +
  'start_date AS "startDate", ' +
  'end_date AS "endDate" ';

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_FIXED_FUND', message);
}

function isIntegerText(value: unknown): boolean {
  return (typeof value === 'number' || typeof value === 'string') && /^\d+$/.test(String(value).trim());
}

function readFixedFund(data: Record<string, unknown>) {
  const name = typeof data['fixedFundName'] === 'string' ? data['fixedFundName'].trim() : '';
  if (name === '' || name.length > 200) {
    throw invalid('고정자금명을 확인해 주세요.');
  }
  if (!isIntegerText(data['fundSubjectId'])) {
    throw invalid('자금과목을 선택해 주세요.');
  }
  const rawAmount = data['amount'];
  const amountText = typeof rawAmount === 'number' || typeof rawAmount === 'string' ? String(rawAmount).trim() : '';
  if (amountText === '' || !/^\d+(\.\d{1,2})?$/.test(amountText) || Number(amountText) <= 0) {
    throw invalid('금액은 0보다 큰 숫자로 입력해 주세요.');
  }
  const direction = data['cashDirection'];
  if (typeof direction !== 'string' || !DIRECTIONS.includes(direction)) {
    throw invalid('입출금 구분을 확인해 주세요.');
  }
  const cycle = data['occurrenceCycle'];
  if (typeof cycle !== 'string' || !CYCLES.includes(cycle)) {
    throw invalid('발생 주기를 확인해 주세요.');
  }
  const startDate = data['startDate'];
  if (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate)) {
    throw invalid('발생 시작일을 확인해 주세요.');
  }
  let endDate: string | null = null;
  const rawEnd = data['endDate'];
  if (rawEnd !== undefined && rawEnd !== null && rawEnd !== '') {
    if (typeof rawEnd !== 'string' || !DATE_PATTERN.test(rawEnd)) {
      throw invalid('발생 종료일을 확인해 주세요.');
    }
    if (rawEnd < startDate) {
      throw invalid('발생 종료일은 시작일 이후여야 합니다.');
    }
    endDate = rawEnd;
  }
  return {
    name,
    fundSubjectId: String(data['fundSubjectId']).trim(),
    amount: amountText,
    direction,
    cycle,
    startDate,
    endDate,
  };
}

@Controller('api/v1')
export class FnSfr00906Controller {
  @Get('/fixed-funds')
  async listFixedFunds(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    let size = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const params: Record<string, unknown> = {};
    let where = 'WHERE 1 = 1 ';
    const subject = q['fundSubjectId'];
    if (subject !== undefined && subject !== '') {
      if (!isIntegerText(subject)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '자금과목 형식이 올바르지 않습니다.');
      }
      where += 'AND fund_subject_id = CAST(:fundSubjectId AS bigint) ';
      params['fundSubjectId'] = String(subject).trim();
    }
    const direction = q['cashDirection'];
    if (direction !== undefined && direction !== '') {
      if (typeof direction !== 'string' || !DIRECTIONS.includes(direction)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '입출금 구분이 올바르지 않습니다.');
      }
      where += 'AND cash_direction = :cashDirection ';
      params['cashDirection'] = direction;
    }
    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS "total" ' + 'FROM fixed_fund ' + where, params);
      const items = await db.query(
        'SELECT ' +
          COLUMNS +
          'FROM fixed_fund ' +
          where +
          'ORDER BY fixed_fund_id DESC ' +
          'LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/fixed-funds')
  @HttpCode(200)
  async createFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const v = readFixedFund(data);
    return transaction(async (db) => {
      const subjects = await db.query(
        'SELECT fund_subject_id FROM fund_subject ' + 'WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
        { fundSubjectId: v.fundSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목이 존재하지 않습니다.');
      }
      const rows = await db.query(
        'INSERT INTO fixed_fund ' +
          '(fixed_fund_name, fund_subject_id, amount, cash_direction, occurrence_cycle, ' +
          'start_date, end_date, created_at, updated_at) ' +
          'VALUES (:name, CAST(:fundSubjectId AS bigint), CAST(:amount AS numeric), :direction, :cycle, ' +
          'CAST(:startDate AS date), CAST(:endDate AS date), now(), now()) ' +
          'RETURNING fixed_fund_id AS "fixedFundId"',
        { ...v },
      );
      return { fixedFundId: Number(rows[0]['fixedFundId']) };
    });
  }

  @Put('/fixed-funds/:fixedFundId')
  async updateFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['fixedFundId'];
    const data = checks.inputOf(req.body);
    if (!/^\d+$/.test(id)) {
      throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
    }
    const v = readFixedFund(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT fixed_fund_id FROM fixed_fund ' + 'WHERE fixed_fund_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
      }
      const subjects = await db.query(
        'SELECT fund_subject_id FROM fund_subject ' + 'WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
        { fundSubjectId: v.fundSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목이 존재하지 않습니다.');
      }
      await db.execute(
        'UPDATE fixed_fund SET ' +
          'fixed_fund_name = :name, ' +
          'fund_subject_id = CAST(:fundSubjectId AS bigint), ' +
          'amount = CAST(:amount AS numeric), ' +
          'cash_direction = :direction, ' +
          'occurrence_cycle = :cycle, ' +
          'start_date = CAST(:startDate AS date), ' +
          'end_date = CAST(:endDate AS date), ' +
          'updated_at = now() ' +
          'WHERE fixed_fund_id = CAST(:id AS bigint)',
        { ...v, id },
      );
      return { fixedFundId: Number(id) };
    });
  }

  @Delete('/fixed-funds/:fixedFundId')
  async deleteFixedFund(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['fixedFundId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
    }
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM fixed_fund ' + 'WHERE fixed_fund_id = CAST(:id AS bigint)',
        { id },
      );
      if (count === 0) {
        throw new ApiError(404, 'FIXED_FUND_NOT_FOUND', '고정자금이 존재하지 않습니다.');
      }
      return {};
    });
  }
}

