import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const DIRECTIONS: [string, string][] = [
  ['입금', '입금'],
  ['출금', '출금'],
];
const CYCLES: [string, string][] = [
  ['MONTHLY', '매월'],
  ['QUARTERLY', '분기'],
  ['YEARLY', '매년'],
  ['ONCE', '1회'],
];

const EMPTY: Row = {
  fixedFundName: '',
  fundSubjectId: '',
  amount: '',
  cashDirection: '',
  occurrenceCycle: '',
  startDate: '',
  endDate: '',
};

type Mode = 'create' | 'edit' | 'delete';

export default function FnSfr00906Page({ role, notify }: PageProps) {
  const [subjectDraft, setSubjectDraft] = useState<number | string>('');
  const [directionDraft, setDirectionDraft] = useState('');
  const [subject, setSubject] = useState<number | string>('');
  const [direction, setDirection] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode | null>(null);
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>(EMPTY);

  const { data, error, reload } = useData<Page>(
    () =>
      call<Page>('GET', '/fixed-funds', role, undefined, {
        fundSubjectId: subject,
        cashDirection: direction,
        page,
        size: SIZE,
      }),
    [subject, direction, page, role],
  );

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openCreate() {
    setTarget(null);
    setForm(EMPTY);
    setMode('create');
  }

  function openEdit(row: Row) {
    setTarget(row);
    setForm({
      fixedFundName: row['fixedFundName'] ?? '',
      fundSubjectId: row['fundSubjectId'] ?? '',
      amount: row['amount'] ?? '',
      cashDirection: row['cashDirection'] ?? '',
      occurrenceCycle: row['occurrenceCycle'] ?? '',
      startDate: row['startDate'] ?? '',
      endDate: row['endDate'] ?? '',
    });
    setMode('edit');
  }

  function openDelete(row: Row) {
    setTarget(row);
    setMode('delete');
  }

  function close() {
    setMode(null);
    setTarget(null);
  }

  function search() {
    setPage(0);
    setSubject(subjectDraft);
    setDirection(directionDraft);
  }

  function reset() {
    setSubjectDraft('');
    setDirectionDraft('');
    setPage(0);
    setSubject('');
    setDirection('');
  }

  function missing(): string {
    if (String(form['fixedFundName'] ?? '').trim() === '') return '고정자금명을 입력해 주세요.';
    if (form['fundSubjectId'] === '' || form['fundSubjectId'] === undefined) return '자금과목을 선택해 주세요.';
    if (form['amount'] === '' || form['amount'] === undefined) return '금액을 입력해 주세요.';
    if (!form['cashDirection']) return '입출금 구분을 선택해 주세요.';
    if (!form['occurrenceCycle']) return '발생 주기를 선택해 주세요.';
    if (!form['startDate']) return '발생 시작일을 입력해 주세요.';
    return '';
  }

  async function save() {
    const message = missing();
    if (message !== '') {
      throw new Error(message);
    }
    const body: Row = {
      fixedFundName: form['fixedFundName'],
      fundSubjectId: form['fundSubjectId'],
      amount: form['amount'],
      cashDirection: form['cashDirection'],
      occurrenceCycle: form['occurrenceCycle'],
      startDate: form['startDate'],
    };
    if (form['endDate']) {
      body['endDate'] = form['endDate'];
    }
    if (mode === 'edit' && target) {
      await call('PUT', '/fixed-funds/' + String(target['fixedFundId']), role, body);
      notify('고정자금을 수정했습니다.');
    } else {
      await call('POST', '/fixed-funds', role, body);
      notify('고정자금을 등록했습니다.');
    }
    close();
    reload();
  }

  async function remove() {
    if (!target) return;
    await call('DELETE', '/fixed-funds/' + String(target['fixedFundId']), role);
    notify('고정자금을 삭제했습니다.');
    close();
    reload();
  }

  const columns: Column[] = [
    { key: 'fixedFundName', label: '고정자금명' },
    {
      key: 'fundSubjectId',
      label: '자금과목',
      render: (row) => <RefName table='fund_subject' role={role} value={row['fundSubjectId']} />,
    },
    { key: 'amount', label: '금액', render: (row) => <Num value={row['amount']} /> },
    { key: 'cashDirection', label: '입출금 구분', render: (row) => <Badge value={row['cashDirection']} /> },
    {
      key: 'occurrenceCycle',
      label: '발생 주기',
      render: (row) => {
        const found = CYCLES.find((c) => c[0] === row['occurrenceCycle']);
        return <span>{found ? found[1] : String(row['occurrenceCycle'] ?? '')}</span>;
      },
    },
    { key: 'startDate', label: '발생 시작일', render: (row) => <DateText value={row['startDate']} /> },
    { key: 'endDate', label: '발생 종료일', render: (row) => <DateText value={row['endDate']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (row) => (
        <span>
          <button
            type='button'
            onClick={(e) => {
              e.stopPropagation();
              openEdit(row);
            }}
          >
            수정
          </button>
          <button
            type='button'
            onClick={(e) => {
              e.stopPropagation();
              openDelete(row);
            }}
          >
            삭제
          </button>
        </span>
      ),
    },
  ];

  const incomeCount = rows.filter((r) => r['cashDirection'] === '입금').length;
  const outgoCount = rows.filter((r) => r['cashDirection'] === '출금').length;

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>고정자금 건수</h2>
        <Num value={total} />
      </section>
      <section className='box span-4'>
        <h2>입금 (현재 쪽)</h2>
        <Num value={incomeCount} />
      </section>
      <section className='box span-4'>
        <h2>출금 (현재 쪽)</h2>
        <Num value={outgoCount} />
      </section>
      <section className='box span-12'>
        <h2>고정자금 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='자금과목'>
            <LookupSelect
              table='fund_subject'
              role={role}
              value={subjectDraft}
              onChange={setSubjectDraft}
              placeholder='전체'
            />
          </Field>
          <Field label='입출금 구분'>
            <Select value={directionDraft} onChange={setDirectionDraft} options={DIRECTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={openCreate}>
            고정자금 등록
          </button>
        </Band>
        {error !== '' && <ErrorText text={error} />}
        <DataTable columns={columns} rows={rows} onRowClick={openEdit} empty='등록된 고정자금이 없습니다.' />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {(mode === 'create' || mode === 'edit') && (
        <Drawer title={mode === 'create' ? '고정자금 등록' : '고정자금 수정'} onClose={close}>
          <Form onSubmit={save} submit={mode === 'create' ? '등록' : '저장'}>
            <Field label='고정자금명' required wide>
              <TextInput value={form['fixedFundName']} onChange={(v) => setField('fixedFundName', v)} />
            </Field>
            <Field label='자금과목' required>
              <LookupSelect
                table='fund_subject'
                role={role}
                value={form['fundSubjectId']}
                onChange={(v) => setField('fundSubjectId', v)}
              />
            </Field>
            <Field label='금액' required>
              <NumberInput value={form['amount']} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label='입출금 구분' required>
              <Select
                value={form['cashDirection']}
                onChange={(v) => setField('cashDirection', v)}
                options={DIRECTIONS}
              />
            </Field>
            <Field label='발생 주기' required>
              <Select
                value={form['occurrenceCycle']}
                onChange={(v) => setField('occurrenceCycle', v)}
                options={CYCLES}
              />
            </Field>
            <Field label='발생 시작일' required>
              <DateInput value={form['startDate']} onChange={(v) => setField('startDate', v)} />
            </Field>
            <Field label='발생 종료일' hint='종료가 정해지지 않았으면 비워 둡니다.'>
              <DateInput value={form['endDate']} onChange={(v) => setField('endDate', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'delete' && target && (
        <Drawer title='고정자금 삭제' onClose={close}>
          <Pairs
            items={[
              ['고정자금명', String(target['fixedFundName'] ?? '')],
              ['자금과목', <RefName table='fund_subject' role={role} value={target['fundSubjectId']} />],
              ['금액', <Num value={target['amount']} />],
              ['입출금 구분', <Badge value={target['cashDirection']} />],
            ]}
          />
          <Form onSubmit={remove} submit='삭제' danger note='삭제한 고정자금은 되돌릴 수 없습니다.' />
        </Drawer>
      )}
    </div>
  );
}
